insert into public.uon_ai_knowledge
(title,content,category,source_url,source_title,official,active,tags)
values
('التقويم الأكاديمي الرسمي','توفر جامعة نزوى صفحة رسمية للتقويم الأكاديمي، وتتضمن روابط الأعوام الأكاديمية الحالية ومنها 2025-2026 و2026-2027. يجب الرجوع إلى الصفحة الرسمية عند السؤال عن مواعيد التسجيل أو الحذف والإضافة أو الاختبارات أو بداية ونهاية الفصول.','calendar','https://www.unizwa.edu.om/index.php?contentid=1071&lang=ar','التقويم الأكاديمي - جامعة نزوى',true,true,array['التقويم','مواعيد','اختبارات','تسجيل','حذف وإضافة']),
('اللوائح الأكاديمية','تنشر جامعة نزوى اللوائح الأكاديمية والسياسات والإرشادات من خلال قسم الشؤون الأكاديمية. يجب إرفاق المصدر الرسمي وعدم إعطاء حكم نهائي في المسائل الأكاديمية أو المالية دون الرجوع إلى اللائحة الحالية والجهة المختصة.','regulations','https://www.unizwa.edu.om/index.php?contentid=505','اللوائح الأكاديمية - جامعة نزوى',true,true,array['لوائح','سياسات','قوانين','أكاديمي']),
('لائحة الإرشاد والحضور والغياب','توجد صفحة رسمية للوائح مركز الإرشاد والمتابعة الأكاديمية، وتشمل لائحة الإرشاد الأكاديمي ولائحة الحضور والغياب. عند السؤال عن الغياب أو الإنذار أو الإرشاد يجب توجيه الطالب لهذه اللوائح والجهة المختصة.','regulations','https://www.unizwa.edu.om/index.php?contentid=1718','اللوائح - جامعة نزوى',true,true,array['غياب','حضور','إنذار','إرشاد أكاديمي']),
('الخدمات الإلكترونية والمنظومة التعليمية','تقدم المنظومة التعليمية بجامعة نزوى خدمات القبول والتسجيل ومتابعة الوضع الأكاديمي والتواصل مع أعضاء هيئة التدريس وإدارة الجامعة. وتعرض الجامعة روابط المنظومة التعليمية والمنظومة الإدارية ونظام إدارة المساقات.','e-services','https://www.unizwa.edu.om/index.php?contentid=291','المنظومة التعليمية والمنظومة الإدارية - جامعة نزوى',true,true,array['EduWave','المنظومة التعليمية','تسجيل','خدمات إلكترونية']),
('موودل وإدارة المساقات','تدعم جامعة نزوى التعليم الإلكتروني، وتوفر نظام إدارة المساقات موودل ضمن خدماتها الإلكترونية. يستخدم للوصول إلى محتوى المقررات والأنشطة التي يتيحها المحاضر.','e-learning','https://www.unizwa.edu.om/index.php?contentid=673','التعليم الإلكتروني - جامعة نزوى',true,true,array['Moodle','موودل','تعليم إلكتروني','مساقات']),
('موارد وخدمات الطلاب','تجمع صفحة الموارد والخدمات الرسمية روابط الخدمات الأكاديمية والخدمات الطلابية المساندة، ومنها المكتبة ومركز مهارات الكتابة ومركز تعزيز مسالك التعلم ومركز ريادة الأعمال وعمادة القبول والتسجيل وعمادة شؤون الطلاب وخدمة المجتمع ومركز الإرشاد والمتابعة الأكاديمية.','student-services','https://www.unizwa.edu.om/index.php?contentid=612','الموارد والخدمات - جامعة نزوى',true,true,array['خدمات الطلاب','المكتبة','مركز الكتابة','الإرشاد','القبول والتسجيل']),
('خدمات الطلبة داخل الحرم','تعرض الجامعة في صفحة خدمات الطلبة معلومات وروابط عن المكتبة الرئيسية والمجموعات الطلابية والصحة والسلامة والمسجد ومصلى النساء وخيارات الطعام والسوبرماركت والسكن ورسوم الدراسة.','student-life','https://www.unizwa.edu.om/index.php?contentid=2892','خدمات الطلبة - جامعة نزوى',true,true,array['سكن','طعام','مكتبة','صحة وسلامة','رسوم','مجموعات طلابية']),
('التسجيل الإلكتروني','توفر جامعة نزوى صفحة تسجيل إلكتروني تجمع مسارات التقديم المناسبة، ومنها الدراسات العليا والطلبة العمانيون للتخصصات غير التربوية والطلبة الدوليون والتخصصات التربوية. حالة فتح أو إغلاق كل مسار قد تتغير، لذلك يجب التحقق من الصفحة وقت السؤال.','admissions','https://www.unizwa.edu.om/index.php?contentid=2562','التسجيل الإلكتروني - جامعة نزوى',true,true,array['قبول','تسجيل إلكتروني','تقديم','دراسات عليا','طلاب دوليون']),
('برامج البكالوريوس','تعرض جامعة نزوى برامج درجة البكالوريوس ضمن الشؤون الأكاديمية، إضافة إلى فهرس التخصصات وتفاصيل المواد ومتطلبات الجامعة والبرنامج التأسيسي. يعتمد UON AI على روابط البرامج الرسمية عند عرض معلومات التخصصات والخطط.','programs','https://www.unizwa.edu.om/index.php?contentid=623','برامج درجة البكالوريوس - جامعة نزوى',true,true,array['بكالوريوس','برامج','تخصصات','خطط دراسية']),
('الشؤون الأكاديمية','تجمع صفحة الشؤون الأكاديمية روابط الكليات والمعاهد ومكتب نائب الرئيس للشؤون الأكاديمية والدراسات العليا وعمادة التعلم الإلكتروني وعمادة القبول والتسجيل واللوائح الأكاديمية وفهرس التخصصات وتفاصيل المواد ومتطلبات الجامعة.','academic-affairs','https://www.unizwa.edu.om/index.php?contentid=614','الشؤون الأكاديمية - جامعة نزوى',true,true,array['شؤون أكاديمية','قبول وتسجيل','دراسات عليا','تفاصيل المواد']),
('التواصل العام مع الجامعة','رقم الاستفسارات العامة الظاهر في الموقع الرسمي لجامعة نزوى هو 0096825446234. قد توجد أرقام مخصصة لوحدات أخرى؛ يجب استخدام صفحة الجهة الرسمية أو دليل الموظفين عند طلب جهة محددة.','contact','https://www.unizwa.edu.om/','جامعة نزوى - الموقع الرسمي',true,true,array['اتصال','هاتف','استفسارات','رقم الجامعة']);
